/* HERO_TREE_VIEW_BEGIN */
const HERO_TREES = {
  warrior: [['arms','Оружие'],['fury','Неистовство'],['prot','Защита']],
  paladin: [['holy','Свет'],['prot','Защита'],['ret','Воздаяние']],
  druid: [['balance','Баланс'],['feral','Сила зверя'],['resto','Исцеление']],
  priest: [['disc','Послушание'],['holy','Свет'],['shadow','Тьма']],
  mage: [['arcane','Тайная магия'],['fire','Огонь'],['frost','Лёд']],
  hunter: [['bm','Повелитель зверей'],['mm','Стрельба'],['surv','Выживание']],
  rogue: [['assn','Ликвидация'],['combat','Бой'],['subt','Скрытность']],
  warlock: [['aff','Колдовство'],['demo','Демонология'],['destro','Разрушение']]
};
function heroTreeLeaders(totals) {
  if (!totals.length || totals.some(n => !Number.isSafeInteger(n) || n < 0)) return [];
  const max = Math.max(...totals);
  return max > 0 ? totals.flatMap((n,i) => n === max ? [i] : []) : [];
}
function heroTreeTotals() {
  const rows = HERO_TREES[S.main] || [], totals = rows.map(() => 0);
  if (S.main === 'warrior' && S.hero) {
    const v = B.armsIntegrated.validate(S.hero.armsTalents || {}, hLevel('me'));
    totals[0] = v.ok ? v.spent : null;
  }
  return totals;
}
function heroTreeButtons(opened) {
  const totals = heroTreeTotals(), leaders = heroTreeLeaders(totals);
  return '<div role="group" aria-label="Деревья талантов" style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px">' + (HERO_TREES[S.main] || []).map((row,i) => '<button type="button" class="btn" data-tree-view="'+row[0]+'" data-primary-tree="'+leaders.includes(i)+'"'+(opened===row[0]?' aria-current="page"':'')+' style="min-height:48px;min-width:0;white-space:normal;overflow-wrap:anywhere;'+(leaders.includes(i)?'border:2px solid #e4bd52;':'')+'">'+esc(row[1])+'<br><small>Очки: '+(totals[i]===null?'?':totals[i])+(leaders.includes(i)?' · основное':'')+(opened===row[0]?' · просмотр':'')+'</small></button>').join('')+'</div>';
}
function openHeroTree(id, trigger) {
  const tree = (HERO_TREES[S.main] || []).find(row => row[0] === id);
  if (!tree || !S.hero) return;
  let dialog = document.querySelector('#w-hero > dialog[data-tree-screen]');
  if (!dialog) {
    dialog = document.createElement('dialog'); dialog.dataset.treeScreen = '';
    dialog.setAttribute('aria-label','Просмотр дерева талантов');
    dialog.style.cssText = 'position:fixed;inset:0;margin:0;width:100vw;max-width:100vw;height:100dvh;max-height:100dvh;box-sizing:border-box;padding:12px;overflow:auto;overscroll-behavior:contain;padding-bottom:40dvh';
    $('w-hero').append(dialog);
    dialog.addEventListener('close', () => {
      document.querySelectorAll('#w-hero [data-tree-view]').forEach(b => b.removeAttribute('aria-current'));
      if (dialog.treeReturn?.isConnected) dialog.treeReturn.focus({preventScroll:true});
    });
    dialog.addEventListener('click', ev => {
      const node = ev.target.closest('[data-tree-node]');
      if (!node) return;
      const n = B.armsIntegrated.TREE.find(x => x.id === node.dataset.treeNode);
      if (!n) return;
      const effect = armsHeroEffect(n.id);
      dialog.querySelector('[data-tree-inspector]').hidden = false;
      dialog.querySelector('[data-tree-description]').textContent = n.ru + ': ' + (effect === 'Этот талант пока недоступен для изучения.' ? 'Описание эффекта ещё не проверено.' : effect) + (B.armsIntegrated.CONFIG.unavailable.includes(n.id) ? ' Узел закрыт в текущей реализации; причина требует отдельной проверки.' : '');
    });
  }
  if (!dialog.open) dialog.treeReturn = trigger;
  dialog.innerHTML = '<header><h2>'+esc(tree[1])+'</h2><button type="button" class="btn" data-tree-close style="min-height:44px">Назад к герою</button></header>'+heroTreeButtons(id)+'<p>Просмотр не меняет боевой набор или сохранённые очки. Распределение между тремя деревьями ещё не подключено.</p>'+(S.main==='druid' && id==='feral'?'<p>Медведь и кошка относятся к этому дереву. Их боевые профили и механики сохранены раздельно.</p>':'')+'<aside data-tree-inspector hidden style="position:fixed;left:12px;right:12px;bottom:60px;max-height:30dvh;overflow:auto;background:var(--panel,#222);color:var(--ink,#fff);border:1px solid;padding:8px;z-index:2"><button type="button" class="btn" data-tree-hide>Скрыть описание</button><p data-tree-description role="status" style="overflow-wrap:anywhere"></p></aside><div data-tree-body></div><footer style="position:sticky;bottom:0;background:var(--panel,#222);padding:6px"><button type="button" class="btn" data-tree-close style="min-height:44px;width:100%">Назад к герою</button></footer>';
  dialog.querySelectorAll('[data-tree-close]').forEach(b => { b.onclick = () => dialog.close(); });
  dialog.querySelector('[data-tree-hide]').onclick = () => { dialog.querySelector('[data-tree-inspector]').hidden = true; };
  const body = dialog.querySelector('[data-tree-body]');
  if (S.main === 'warrior' && id === 'arms' && ARMS_HERO_MODE) {
    const P = B.armsIntegrated, raw = S.hero.armsTalents || {}, valid = P.validate(raw,hLevel('me')).ok;
    body.innerHTML = '<p>Текущее дерево Arms. Только просмотр: нажатие показывает описание, очки не тратятся. Баланс временный.</p>' + (valid?'':'<p role="alert">Сохранённые ранги не прошли проверку. Они не изменены.</p>') + [...new Set(P.TREE.map(n=>n.tier))].sort((a,b)=>a-b).map(tier => '<section><h3>Ряд '+tier+'</h3><div style="display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px">'+P.TREE.filter(n=>n.tier===tier).map(n=>'<button type="button" class="btn" data-tree-node="'+esc(n.id)+'" style="min-height:48px;min-width:0;white-space:normal;overflow-wrap:anywhere">'+esc(n.ru)+'<br>'+esc(valid?(raw[n.id]||0):'?')+'/'+n.max+'</button>').join('')+'</div></section>').join('');
  } else body.textContent = 'Данные этого дерева ещё не подключены к просмотру. Здесь нельзя тратить очки или менять боевую специализацию.';
  document.querySelectorAll('#w-hero [data-tree-view]').forEach(b => {
    if (b.dataset.treeView === id) b.setAttribute('aria-current','page'); else b.removeAttribute('aria-current');
  });
  if (!dialog.open) dialog.showModal();
  dialog.scrollTop = 0;
  dialog.querySelector('[data-tree-close]').focus({preventScroll:true});
}
/* HERO_TREE_VIEW_END */

